{
  "headline": "FDA's records trace our voriconazole supply to a plant classified OAI 2552 days before the posting",
  "headline_cites": ["E5", "D4"],
  "sentences": [
    {
      "text": "All three Corvale sites stock voriconazole tablets labeled by Aurobindo Pharma Limited under NDC 65862089103.",
      "cites": ["E1", "E2", "E3"]
    },
    {
      "text": "The product label identifies the registered manufacturing plant as Aurobindo Pharma Limited, FEI 3007373532, in India.",
      "cites": ["E7"]
    },
    {
      "text": "FDA inspection 1105823 of that plant ended on 2019-09-27 and was classified Official Action Indicated (OAI), with the classification known to FDA on 2019-12-26.",
      "cites": ["E5"]
    },
    {
      "text": "That OAI classification occurred 2552 days before the shortage posting date of 2026-10-21.",
      "cites": ["D4"]
    },
    {
      "text": "A later inspection 1169446 ended 2022-05-10 and was classified Voluntary Action Indicated (VAI).",
      "cites": ["E6"]
    },
    {
      "text": "Corvale East has 6.3 days of supply on hand, Corvale Lakeside has 26 days and can spare 36 units while retaining two weeks of stock, and Corvale General holds 21 days.",
      "cites": ["D1", "D2", "D3"]
    },
    {
      "text": "The recommended action is to transfer 36 units from Corvale Lakeside to Corvale East, raising East to approximately 9 days on hand.",
      "cites": ["D1", "D3"]
    }
  ]
}
